import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_columns = [
        "state", "office", "pollster", "start_date", "end_date", "n",
        "population", "dem_name", "rep_name", "dem", "rep", "other",
        "und", "source", "exact",
    ]
    width = len(expected_columns)

    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"')
    records = []
    for record in reader:
        if not record or not any(value.strip() for value in record):
            continue
        records.append([value.lstrip("\ufeff") if i == 0 else value
                        for i, value in enumerate(record)])

    header_index = None
    required = set(expected_columns[:5])
    for i, record in enumerate(records):
        normalized = [re.sub(r"\s+", "_", value.strip().lower()) for value in record]
        if required.issubset(set(normalized)):
            header_index = i
            break

    if header_index is None:
        if not records:
            return {"columns": expected_columns, "rows": []}
        header_index = 0

    columns = records[header_index]
    if len(columns) < width:
        columns = columns + [""] * (width - len(columns))
    elif len(columns) > width:
        columns = columns[:width - 1] + [",".join(columns[width - 1:])]

    rows = []
    for record in records[header_index + 1:]:
        if len(record) < width:
            record = record + [""] * (width - len(record))
        elif len(record) > width:
            record = record[:width - 1] + [",".join(record[width - 1:])]
        rows.append(record)

    return {"columns": columns, "rows": rows}
